function IdolLive3D_RoleAnimatorMgrV2B:__init( mainForRuntime_, animator_, animatorController_ )

    assert(isNotNull(animator_))
    --assert(isNotNull(animatorController_))
    --- 
    self.mainForRuntime = mainForRuntime_
    self.baseJson = mainForRuntime_.baseJson
    self.animator = animator_
    self.animator.runtimeAnimatorController = nil
    self.roleGO = self.animator.gameObject 

    --  Animancer:
    self.roleAnimancer = KTool.GetOrAddComponent(self.roleGO, typeof(AnimancerComponent))
    self.roleAnimancer.Animator = self.animator

    self.animatorState = IdolLive3D_States.AnimatorState.Idle
    self.frontStageJson = nil -- 临时绑定的 stage json;
    --
    self.isInit = true
end



function IdolLive3D_RoleAnimatorMgrV2B:__delete()
end




-- ===============================================================


-- 外部调用, 在进入一个新的 stage 之前, 本实例需要做的所有准备工作:
---@param isJumpToIdle_ boolean | nil @ 若设为 true, 将无视 toIdle 动画, 直接硬跳入 idle 动画
function IdolLive3D_RoleAnimatorMgrV2B:SwitchToNewStage( newStageJson_, isJumpToIdle_ ) -- v2B
    if self.isInit ~= true then 
        printError("未初始化")
        return nil
    end  
    ---
    local lastStageJson = self.frontStageJson -- cached
    self.frontStageJson = newStageJson_
    ---

    -- ==1== 直接跳入 Idle:
    if isJumpToIdle_ == true or isNull(lastStageJson) then 
        self:BackToIdle()
        return
    end 

    local stageJump = lastStageJson.stageJumps[newStageJson_.stageName]
    if isNull(stageJump) then 
        printError("是不是 json 中漏配了 stageJump; from: " .. tostring(lastStageJson.stageName) .. " to " .. tostring(newStageJson_.stageName))
        self:BackToIdle()
        return
    end 

    ---
    local toIdleAnimClipGO = stageJump.animClipGO


    if isNull(toIdleAnimClipGO) then
        printError("没找到 to idle 动画片段")
        self:BackToIdle()
        return
    end 


    self:PlaySimpleIStateGO( toIdleAnimClipGO )
end





-- ================================================


---@return boolean
function IdolLive3D_RoleAnimatorMgrV2B:IsAnimatorStateInfoInIdle()
    if self.isInit ~= true then 
        printError("未初始化")
        return false
    end 
    return self.animatorState == IdolLive3D_States.AnimatorState.Idle
end



function IdolLive3D_RoleAnimatorMgrV2B:FindCurrentPlayingIdleState() 
    if self:IsAnimatorStateInfoInIdle() == false then 
        return nil
    end 
    return self.frontStageJson.idleState
end




function IdolLive3D_RoleAnimatorMgrV2B:BackToIdle()
    local idleClipGO = self.frontStageJson.animClips[StageClipNames.Idle]
    local fadeTime = 0.25
    self.roleAnimancer:Play(idleClipGO, fadeTime)
    self.animatorState = IdolLive3D_States.AnimatorState.Idle
end



function IdolLive3D_RoleAnimatorMgrV2B:PlaySimpleIState( iState_ )
    local animClipGO = iState_.animClipGO
    self:PlaySimpleIStateGO(animClipGO)
end


function IdolLive3D_RoleAnimatorMgrV2B:PlaySimpleIStateGO( animClipGO_ )

    local idleClipGO = self.frontStageJson.animClips[StageClipNames.Idle]
    local fadeTime = 0.25
    ---
    self.animatorState = IdolLive3D_States.AnimatorState.SimpleIState

    self:PlayAnimClip( animClipGO_, idleClipGO, fadeTime, function()
        self.animatorState = IdolLive3D_States.AnimatorState.Idle
    end ) 
end




function IdolLive3D_RoleAnimatorMgrV2B:PlayAnimClip( animClipGO_, endAnimClipGO_, fadeTime_, endCB_ ) 
    assert( isNotNull(animClipGO_) )
    assert( isNotNull(endAnimClipGO_) )
    if type(fadeTime_) ~= "number" then 
        fadeTime_ = 0.25
    end 
    local retState = self.roleAnimancer:Play(animClipGO_)
    if isNotNull(retState) then
        retState.Events:SetEndAction(function() 
            --printError("end")
            self.roleAnimancer:Play(endAnimClipGO_, fadeTime_)
            if isNotNull(endCB_) then 
                endCB_()
            end 
        end)
    end
end










return IdolLive3D_RoleAnimatorMgrV2B
